parameters.jsCode:
// Připraví kandidáty pro hledání v Raynetu.
// Klíčová myšlenka: nehledáme celé jméno (skloňování + diakritika),
// ale KMEN PŘÍJMENÍ. "Višinskou" i "Višinská" -> "Višin".

const out = $json.output || {};
const t = $('Get Fireflies Transcript').first().json.data.transcript || {};

const strip = (s) => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const first = (out.clientFirstName || '').trim();
const last  = (out.clientLastName || '').trim();

// useknu koncovku -> obejdu skloňování ("Višinskou" -> "Višinsk")
const stem = last.length > 5 ? last.slice(0, -2) : last;

const organizer = (t.organizer_email || '').toLowerCase();
const participants = (t.participants || []).filter(p => typeof p === 'string');
const clientEmail = (
  out.clientEmail ||
  participants.find(p => p.toLowerCase() !== organizer && p.includes('@')) ||
  ''
).toLowerCase();

const confidence = out.confidence || 'low';

return [{
  json: {
    meetingId: $('Vstup: meetingId').first().json.meetingId,
    clientFirstName: first,
    clientLastName: last,
    clientName: (first + ' ' + last).trim(),
    clientNameAscii: strip((first + ' ' + last).trim()).toLowerCase(),
    clientEmail,
    confidence,
    clientNameSource: out.clientNameSource || 'unknown',
    stem,
    stemAscii: strip(stem),
    meetingTitle: t.title || '',
    organizerEmail: t.organizer_email || '',
    // pojistka: bez příjmení nebo při nízké jistotě do CRM vůbec nesaháme
    skipCrm: !last || confidence === 'low',
    shrnutiOdstavce: out.shrnutiOdstavce || [],
    dulezitebody: out.dulezitebody || []
  }
}];

// Sloučí výsledky obou hledání, oboduje kandidáty a rozhodne,
// jestli je shoda jednoznačná. Tady se dělá skutečné párování - ne v API dotazu.

const prep = $('Připravit hledání').first().json;

const strip = (s) => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

// --- posbírej kandidáty z obou hledání a zaznamenej, pokud samotné hledání selhalo ---
const searchErrors = [];
const collect = (nodeName) => {
  let items = [];
  try {
    items = $(nodeName).all();
  } catch (e) {
    return [];
  }
  return items.flatMap(i => {
    if (i.json && Array.isArray(i.json.data)) return i.json.data;
    if (i.json && i.json.error) {
      searchErrors.push(nodeName + ': ' + JSON.stringify(i.json.error).slice(0, 300));
    }
    return [];
  });
};

const raw = [...collect('Hledat klienta – příjmení'), ...collect('Hledat klienta – fulltext')];

// deduplikace podle id
const byId = {};
for (const c of raw) { if (c && c.id) byId[c.id] = c; }
const candidates = Object.values(byId);

// --- vytáhni e-mail z Raynet záznamu (je zanořený v adresách) ---
const emailOf = (c) => {
  const buckets = [];
  if (c.primaryAddress) buckets.push(c.primaryAddress);
  if (Array.isArray(c.addresses)) buckets.push(...c.addresses);
  if (c.contactInfo) buckets.push({ contactInfo: c.contactInfo });
  for (const b of buckets) {
    const e = b && b.contactInfo && b.contactInfo.email;
    if (e) return String(e).toLowerCase();
  }
  return '';
};

// --- bodování ---
const wantEmail = (prep.clientEmail || '').toLowerCase();
const wantLast  = strip(prep.clientLastName);
const wantFirst = strip(prep.clientFirstName);
const wantStem  = strip(prep.stem);

const scored = candidates.map(c => {
  const name = strip(c.name);
  const cLast = strip(c.lastName);
  const cFirst = strip(c.firstName);
  const cEmail = emailOf(c);

  let score = 0;
  const why = [];
  if (wantEmail && cEmail && cEmail === wantEmail) { score += 100; why.push('email'); }
  if (wantLast && cLast && cLast === wantLast)     { score += 50;  why.push('příjmení'); }
  if (wantFirst && cFirst && cFirst === wantFirst) { score += 25;  why.push('křestní'); }
  if (wantLast && !cLast && name.includes(wantLast)) { score += 40; why.push('jméno obsahuje příjmení'); }
  if (wantFirst && name.includes(wantFirst))       { score += 10;  why.push('jméno obsahuje křestní'); }
  if (wantStem && name.includes(wantStem))         { score += 10;  why.push('kmen'); }

  return { id: c.id, name: c.name, email: cEmail, score, why: why.join(', ') };
}).sort((a, b) => b.score - a.score);

// --- rozhodnutí ---
let matchStatus = 'notfound';
let match = null;

if (prep.skipCrm) {
  matchStatus = 'skipped';
} else if (searchErrors.length > 0 && scored.length === 0) {
  // Hledání v Raynetu selhalo (API/síť) a nemáme žádné kandidáty -> nevíme,
  // jestli klient existuje. NESMÍ se to vydávat za "nenalezeno", ať se kvůli
  // výpadku API nezaloží zbytečně duplicitní klient.
  matchStatus = 'search_error';
} else if (scored.length === 0) {
  matchStatus = 'notfound';
} else {
  const top = scored[0];
  const second = scored[1];
  const clearWinner = !second || (top.score - second.score) >= 25;
  if (top.score >= 50 && clearWinner) {
    matchStatus = 'matched';
    match = top;
  } else if (top.score >= 50) {
    matchStatus = 'ambiguous';
  } else {
    matchStatus = 'notfound';
  }
}

// --- texty pro zápis a email ---
const summaryText = (prep.shrnutiOdstavce || []).join('\n\n');
const keyPointsText = (prep.dulezitebody || []).join('\n- ');
const htmlBody =
  '<h2>Výsledek jednání</h2><p><em>Shrnutí</em></p>' +
  (prep.shrnutiOdstavce || []).map(p => '<p>' + p + '</p>').join('') +
  '<p><strong>Důležité body:</strong></p><ul>' +
  (prep.dulezitebody || []).map(b => '<li>' + b + '</li>').join('') +
  '</ul>';

return [{
  json: {
    matchStatus,
    meetingId: prep.meetingId,
    companyId: match ? match.id : null,
    matchedName: match ? match.name : null,
    matchReason: match ? match.why : null,
    clientFirstName: prep.clientFirstName,
    clientLastName: prep.clientLastName,
    clientEmailForDraft: prep.clientEmail || (match ? match.email : '') || '',
    clientName: prep.clientName,
    confidence: prep.confidence,
    clientNameSource: prep.clientNameSource,
    meetingTitle: prep.meetingTitle,
    summaryText,
    keyPointsText,
    htmlBody,
    searchErrorInfo: searchErrors.join(' | '),
    candidatesPreview: scored.slice(0, 5)
      .map(c => `#${c.id} ${c.name} (skóre ${c.score}${c.why ? ', ' + c.why : ''})`)
      .join('\n') || '(žádní kandidáti)'
  }
}];

// Výchozí hodnoty pro založení NOVÉHO klienta v Raynetu.
// !! owner.id MUSÍ být reálné ID uživatele (poradce) v Raynetu - bez něj API
// založení odmítne. role/state/rating uprav podle vlastního nastavení v Raynetu
// (Nastavení -> Firmy -> stavy/hodnocení), tady jsou jen rozumné výchozí hodnoty.
return [{
  json: {
    ...$json,
    raynetOwnerId: 0, // TODO: doplnit skutečné ID vlastníka v Raynetu
    raynetRole: 'A_SUBSCRIBER',
    raynetState: 'B_ACTUAL',
    raynetRating: 'B'
  }
}];

// Klient byl v Raynetu úspěšně založen - sloučí jeho nové ID zpátky
// s daty ze schůzky, aby pokračoval do stejného zápisu aktivity jako
// klienti, kteří už v Raynetu existovali.
const created = $json;
const original = $('Vyhodnotit shodu').first().json;
return [{
  json: {
    ...original,
    companyId: created.id,
    matchStatus: 'created'
  }
}];

// Založení nového klienta v Raynetu selhalo (např. špatné owner.id,
// chybějící povinné pole, výpadek API). Notes ze schůzky se nesmí ztratit
// potichu - jde to na ruční kontrolu s detailem chyby.
const original = $('Vyhodnotit shodu').first().json;
return [{
  json: {
    ...original,
    matchStatus: 'create_failed',
    createError: JSON.stringify($json).slice(0, 2000)
  }
}];

