// Cisty vystup sub-workflow pro volajici (webhook / vecerni dohledani).
const src = $('Aktivita v Raynetu zapsána?').first().json;
return [{
  json: {
    meetingId: src.meetingId,
    meetingTitle: src.meetingTitle,
    matchStatus: src.matchStatus,
    clientName: src.clientName,
    companyId: src.companyId || null
  }
}];

// Cisty vystup sub-workflow pro volajici (webhook / vecerni dohledani).
// Predchozi krok muze byt jeden ze tri uzlu podle toho, kudy exekuce prosla -
// vyzkousej je v poradi, prvni existujici pouzij.
function fromFirst(names) {
  for (const n of names) {
    try {
      const items = $(n).all();
      if (items.length) return items[0].json;
    } catch (e) {}
  }
  return {};
}
const src = fromFirst([
  'Klient v Raynetu nenalezen – založit nového?',
  'Připravit selhání založení klienta',
  'Připravit selhání zápisu aktivity'
]);
return [{
  json: {
    meetingId: src.meetingId,
    meetingTitle: src.meetingTitle,
    matchStatus: src.matchStatus,
    clientName: src.clientName,
    companyId: src.companyId || null
  }
}];
